[{"name_path": "makeRunner", "kind": "Function", "relative_path": "src/runner/run.ts", "body_location": {"start_line": 348, "end_line": 409}, "body": "export function makeRunner(
  cfg: Config,
  defaultSignal?: AbortSignal,
  runProc: typeof runProcess = runProcess
): Runner {
  return async (
    seat: Seat,
    agentId: string,
    prompt: string,
    cwd: string,
    logFile: string,
    options?: { signal?: AbortSignal; images?: string[] }
  ): Promise<TurnOutput> => {
    const agent = cfg.agents[agentId];
    if (!agent) {
      throw new Error(`Agent '${agentId}' not found in config`);
    }

    const timeoutMin = cfg.turn.timeout_minutes[seat];
    const timeoutMs = timeoutMin * 60 * 1000;
    const allow = cfg.runner.agy_allow_commands;

    const absLogFile = resolve(logFile);
    mkdirSync(dirname(absLogFile), { recursive: true });
    const outFile = absLogFile.endsWith('.log')
      ? absLogFile.slice(0, -4) + '.out'
      : `${absLogFile}.out`;

    const argv = buildArgv(agent.tool, prompt, {
      seat,
      timeoutMin,
      allow,
      outFile,
      images: options?.images,
    });

    const result = await runProc(argv, {
      cwd,
      timeoutMs,
      logFile: absLogFile,
      env: process.env,
      signal: options?.signal ?? defaultSignal,
    });

    let lastMessage = '';
    if (existsSync(outFile)) {
      try {
        lastMessage = readFileSync(outFile, 'utf8');
      } catch {
        // Fallback to output
      }
    }
    if (!lastMessage) {
      lastMessage = result.output.slice(-2000);
    }

    return {
      ...result,
      lastMessage,
    };
  };
}"}]

