[{"name_path": "runProcess", "kind": "Function", "relative_path": "src/runner/run.ts", "body_location": {"start_line": 59, "end_line": 333}, "body": "export function runProcess(
  argv: string[],
  o: { cwd: string; timeoutMs: number; logFile: string; env?: NodeJS.ProcessEnv; signal?: AbortSignal }
): Promise<ProcResult> {
  return new Promise((resolve, reject) => {
    if (argv.length === 0) {
      reject(new Error('argv must not be empty'));
      return;
    }

    const startTime = Date.now();
    try {
      mkdirSync(dirname(o.logFile), { recursive: true });
    } catch {
      // Ignore directory creation error; logStream error will be handled
    }

    let logStreamError = false;
    let logStream: ReturnType<typeof createWriteStream> | null = null;
    try {
      logStream = createWriteStream(o.logFile, { flags: 'w' });
      logStream.on('error', () => {
        logStreamError = true;
      });
    } catch {
      logStreamError = true;
    }

    let timedOut = false;
    let aborted = false;
    let killInitiated = false;
    let timer: NodeJS.Timeout | null = null;
    let killTimer: NodeJS.Timeout | null = null;
    let groupCheckInterval: NodeJS.Timeout | null = null;
    let sigkillSent = false;
    let childClosed = false;
    let childCloseCode: number | null = null;
    let resolved = false;
    let streamEnded = false;
    const outputChunks: Buffer[] = [];
    const descendants = new Set<number>();

    const isPidDead = (pid: number): boolean => {
      try {
        process.kill(pid, 0);
        return false;
      } catch (err: any) {
        return err?.code === 'ESRCH';
      }
    };

    const isGroupDead = (pgid: number): boolean => {
      try {
        process.kill(-pgid, 0);
        return false;
      } catch (err: any) {
        return err?.code === 'ESRCH';
      }
    };

    const areAllDead = (): boolean => {
      if (childPid && !isGroupDead(childPid)) {
        return false;
      }
      for (const pid of descendants) {
        if (!isPidDead(pid)) {
          return false;
        }
      }
      return true;
    };

    const abortListener = () => {
      aborted = true;
      killAll();
    };

    const cleanup = () => {
      if (timer) {
        clearTimeout(timer);
        timer = null;
      }
      if (groupCheckInterval) {
        clearInterval(groupCheckInterval);
        groupCheckInterval = null;
      }
      if (killTimer) {
        clearTimeout(killTimer);
        killTimer = null;
      }
      if (o.signal && abortListener) {
        o.signal.removeEventListener('abort', abortListener);
      }
    };

    const endLogStream = (cb: () => void) => {
      if (streamEnded) {
        cb();
        return;
      }
      streamEnded = true;
      if (logStream && !logStreamError) {
        logStream.end(() => {
          cb();
        });
        logStream.once('error', () => {
          cb();
        });
      } else {
        cb();
      }
    };

    const finish = () => {
      if (resolved) return;
      resolved = true;
      cleanup();
      endLogStream(() => {
        const durationMs = Date.now() - startTime;
        const output = Buffer.concat(outputChunks).toString('utf8');
        if (aborted) {
          const err = new Error('The operation was aborted');
          err.name = 'AbortError';
          (err as any).result = {
            exitCode: childCloseCode,
            timedOut,
            durationMs,
            output,
          };
          reject(err);
          return;
        }
        resolve({
          exitCode: childCloseCode,
          timedOut,
          durationMs,
          output,
        });
      });
    };

    const maybeFinish = () => {
      if (!childClosed || resolved) {
        return;
      }

      if (!timedOut && !aborted) {
        finish();
        return;
      }

      if (areAllDead()) {
        finish();
        return;
      }

      if (sigkillSent) {
        let retries = 0;
        const ensureDead = () => {
          if (areAllDead() || retries++ > 20) {
            finish();
          } else {
            setTimeout(ensureDead, 25);
          }
        };
        ensureDead();
        return;
      }

      if (!groupCheckInterval) {
        groupCheckInterval = setInterval(() => {
          if (areAllDead()) {
            finish();
          }
        }, 50);
      }
    };

    const killAll = () => {
      if (killInitiated) return;
      killInitiated = true;

      if (childPid) {
        for (const pid of getDescendantPids(childPid)) {
          descendants.add(pid);
        }
        try {
          process.kill(-childPid, 'SIGTERM');
        } catch {}
        for (const pid of descendants) {
          try {
            process.kill(pid, 'SIGTERM');
          } catch {}
        }

        killTimer = setTimeout(() => {
          sigkillSent = true;
          if (childPid) {
            for (const pid of getDescendantPids(childPid)) {
              descendants.add(pid);
            }
            try {
              process.kill(-childPid, 'SIGKILL');
            } catch {}
            for (const pid of descendants) {
              try {
                process.kill(pid, 'SIGKILL');
              } catch {}
            }
          }
          maybeFinish();
        }, 5000);
        maybeFinish();
      } else {
        maybeFinish();
      }
    };

